  Widget _personCard(BuildContext c,Map<String,dynamic>b)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:Row(children:[CircleAvatar(radius:26,backgroundColor:AppColors.paleBlue.withValues(alpha:.35),child:Text('${b['name']??'S'}'.trim().isEmpty?'S':'${b['name']}'.trim()[0].toUpperCase(),style:const TextStyle(color:AppColors.teal,fontWeight:FontWeight.w900))),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${b['name']??'Customer'}',style:Theme.of(c).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w800)),Text('${b['mobile']??'—'} · ${b['place']??'—'}'),Text('Started ${b['start_date']??'—'} · ${b['cycle_days']??30} day cycle',style:Theme.of(c).textTheme.bodySmall)])),Chip(label:Text('${b['status']}'.toUpperCase()))])));
